#!/usr/bin/env node
// Checks the harness stubs against the shapes Rust actually sends.
//
// The browser harness makes the frontend testable without a running app, but a
// stub that drifts from the real payload makes the harness pass while the app
// is broken. That has already happened once: the render stub ignored rotation,
// so the rotation path would have passed its own test while doing nothing.
//
// Fixtures are generated by `cargo test -p easypdf-session --test contract`.
// Run that first; this compares against what it wrote.

import { readFileSync, readdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { createState, handlers } from "../apps/desktop/harness/stubs.js";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const contractDir = join(root, "tests", "contract");

/** How to provoke each fixture's payload out of the stubs. */
const scenarios = {
  open_document: (state) => handlers(state).open_document({ password: null }),

  open_document_error: (state) => {
    state.requirePassword = "secret";
    try {
      handlers(state).open_document({ password: "wrong" });
    } catch (rejection) {
      return rejection;
    }
    throw new Error("open_document was expected to reject without a password");
  },

  page_size: (state) => handlers(state).page_size({ page: 0 }),
  worker_status: (state) => handlers(state).worker_status(),
  search: (state) => handlers(state).search({ query: "EasyPDF" }),
  text_layout: (state) => handlers(state).text_layout({ page: 0 }),

  outline: (state) => {
    state.outline = [
      { title: "Introduction", depth: 0, page: 0 },
      { title: "Unlinked", depth: 1, page: null },
    ];
    return handlers(state).outline();
  },
};

/** Recursively compares key sets. Values are irrelevant; shape is the contract. */
function compareShape(expected, actual, path, problems) {
  const isObject = (v) => v !== null && typeof v === "object" && !Array.isArray(v);

  if (Array.isArray(expected)) {
    if (!Array.isArray(actual)) {
      problems.push(`${path}: expected an array, stub returned ${typeof actual}`);
      return;
    }
    if (expected.length > 0 && actual.length > 0) {
      compareShape(expected[0], actual[0], `${path}[0]`, problems);
    }
    return;
  }

  if (isObject(expected)) {
    if (!isObject(actual)) {
      problems.push(`${path}: expected an object, stub returned ${typeof actual}`);
      return;
    }

    const expectedKeys = Object.keys(expected).sort();
    const actualKeys = Object.keys(actual).sort();

    for (const key of expectedKeys) {
      if (!actualKeys.includes(key)) problems.push(`${path}.${key}: missing from the stub`);
    }
    for (const key of actualKeys) {
      if (!expectedKeys.includes(key)) problems.push(`${path}.${key}: stub sends it, Rust does not`);
    }

    for (const key of expectedKeys) {
      if (actualKeys.includes(key)) {
        compareShape(expected[key], actual[key], `${path}.${key}`, problems);
      }
    }
  }
}

const fixtures = readdirSync(contractDir).filter((name) => name.endsWith(".json"));
if (fixtures.length === 0) {
  console.error("no contract fixtures found — run:");
  console.error("  cargo test -p easypdf-session --test contract");
  process.exit(1);
}

const problems = [];
let checked = 0;

for (const file of fixtures) {
  const name = file.replace(/\.json$/, "");
  const scenario = scenarios[name];

  if (scenario === undefined) {
    problems.push(`${name}: fixture exists but no harness scenario covers it`);
    continue;
  }

  const expected = JSON.parse(readFileSync(join(contractDir, file), "utf8"));
  const actual = scenario(createState());

  const before = problems.length;
  compareShape(expected, actual, name, problems);
  if (problems.length === before) {
    console.log(`  ok    ${name}`);
  }
  checked += 1;
}

for (const name of Object.keys(scenarios)) {
  if (!fixtures.includes(`${name}.json`)) {
    problems.push(`${name}: harness scenario exists but Rust generates no fixture`);
  }
}

if (problems.length > 0) {
  console.error("\nharness stubs do not match what Rust sends:\n");
  for (const problem of problems) console.error(`  ${problem}`);
  console.error("\nA stub that drifts makes the harness pass while the app is broken.");
  process.exit(1);
}

console.log(`\n${checked} contracts match.`);
